export const PEP_TALKS = ["A sharp start. You heard the meaning, not just the sound.","Another Test done. Paraphrases have fewer places to hide now.","That was proper listening work. Keep catching the switch.","You are training the exact instinct IELTS tries to test.","Neat work. Different words, same idea — and you heard it.","One more Test in the bank. Your ear is getting suspicious in the best way.","You caught the disguise. IELTS can change the words, not the meaning.","Good ears. That rephrasing trick is becoming familiar territory.","You are building the habit strong listeners have: listen for the idea.","Quietly excellent. The paraphrase did not get past you.","Test complete. Your listening radar just got a little sharper.","That is how vocabulary becomes listening power.","You did not chase single words. You followed meaning. Exactly right.","Another clean finish. Keep making the connections faster.","The wording changed. You stayed with the message. Well played.","You are learning to hear what IELTS really means, not only what it says.","Strong work. The next Test gets the same treatment.","That was a useful kind of difficult. Your ear just levelled up.","You are turning rephrasing into a reflex. Keep it moving.","Test finished. Those little wording swaps are losing their magic.","Excellent. You spotted the bridge between the question and the audio.","Your listening is becoming less literal and much more accurate.","That is another piece of the IELTS puzzle solved.","You heard past the surface. That is the whole game.","Good. The language shifted, but you did not lose the thread.","A very tidy finish. Let the next Test try its luck.","You are making fast work of IELTS smoke and mirrors.","That was focused listening. The meaning stayed in view.","Another checkpoint cleared. Your paraphrase instinct is alive and well.","Well done. You are hearing relationships, not isolated vocabulary.","The Test changed its clothes. You still recognised it.","One more finished. That is real pattern recognition.","You have made the audio less mysterious and more manageable.","Listening win. The next set has fewer surprises already.","That was a smart finish. Keep trusting the meaning.","Book 20 is underway. Fresh wording, same sharp ear.","Another Book 20 Test cleared. You are catching meaning at speed.","Three down. The paraphrases are changing; your focus is not.","Book 20 complete. You have carried the skill all the way through ten Cambridge books.","Full course complete. You have trained your ear to hear beyond the wording."];

function cleanText(value) {
  const text = String(value).trim().replace(/\s+/g, " ");
  return CORRECTIONS.get(text) || text;
}

function hash(value) {
  let hashValue = 2166136261;
  for (const character of value) {
    hashValue ^= character.codePointAt(0);
    hashValue = Math.imul(hashValue, 16777619);
  }
  return hashValue >>> 0;
}

function uniqueAnswers(rows, excluded) {
  return [...new Set(rows.map((row) => row.answer))].filter((answer) => answer !== excluded);
}

function pickTwo(candidates, seed) {
  const firstIndex = hash(seed) % candidates.length;
  let secondIndex = hash(`${seed}:second`) % candidates.length;
  if (secondIndex === firstIndex) secondIndex = (secondIndex + 1) % candidates.length;
  return [candidates[firstIndex], candidates[secondIndex]];
}

function buildCourse() {
  const raw = SOURCE_DRILLS.map(([book, test, part, question, answer], sourceIndex) => ({
    book,
    test,
    part,
    question: cleanText(question),
    answer: cleanText(answer),
    sourceIndex
  }));

  const testBuckets = new Map();
  for (const item of raw) {
    const key = `${item.book}-${item.test}`;
    if (!testBuckets.has(key)) testBuckets.set(key, []);
    testBuckets.get(key).push(item);
  }

  const tests = [];
  for (const [key, testRows] of testBuckets) {
    const [book, test] = key.split("-").map(Number);
    const partBuckets = new Map();
    for (const row of testRows) {
      if (!partBuckets.has(row.part)) partBuckets.set(row.part, []);
      partBuckets.get(row.part).push(row);
    }

    const testAnswers = uniqueAnswers(testRows, "");
    const drills = testRows.map((row, testIndex) => {
      const partRows = partBuckets.get(row.part);
      const samePart = uniqueAnswers(partRows, row.answer);
      const fallback = uniqueAnswers(testRows, row.answer).filter(
        (answer) => !samePart.includes(answer)
      );
      const candidates = samePart.length >= 2 ? samePart : [...samePart, ...fallback];
      if (candidates.length < 2) {
        throw new Error(`Insufficient answer choices for ${book}-${test}-${row.part}`);
      }

      const [distractor, distractor2] = pickTwo(
        candidates,
        `${book}-${test}-${row.part}-${testIndex}`
      );
      const partIndex = partRows.indexOf(row) + 1;
      return {
        id: `${book}-${test}-${row.part}-${String(partIndex).padStart(2, "0")}`,
        book,
        test,
        part: row.part,
        question: row.question,
        answer: row.answer,
        distractor,
        distractor2,
        distractorScope: samePart.length >= 2 ? "same-part" : "same-test-fallback"
      };
    });

    tests.push({
      id: `${book}-${test}`,
      book,
      test,
      total: drills.length,
      parts: [1, 2, 3, 4].map((number) => ({
        number,
        total: (partBuckets.get(number) || []).length
      })),
      drills
    });
  }

  return tests;
}

export const COURSE = {
  product: "IELTS Listening Paraphrase",
  source: "Cambridge IELTS Books 11–20",
  futureBookReady: 21,
  tests: buildCourse()
};

COURSE.total = COURSE.tests.reduce((sum, test) => sum + test.total, 0);
export const ALL_TESTS = COURSE.tests;
export const ALL_DRILLS = COURSE.tests.flatMap((test) => test.drills);

export function audioKey(text) {
  return text
    .normalize("NFKD")
    .toLowerCase()
    .replace(/[’']/g, "")
    .replace(/&/g, "and")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "")
    .replace(/-{2,}/g, "-");
}

export function audioPath(voice, text) {
  return `/audio/${voice}/${audioKey(text)}.mp3`;
}

export function correctPosition(index) {
  return index % 3;
}
